def count_arrays(N, B):
    MOD = 10**9 + 7
    dp = [1] + [0] * N - 1
    ans = 0

    for b in B:
        for k in range(N - 2, -1, -1):
            if dp[k + 1] == 0:
                dp[k] = 0
            else:
                if b >= dp[k + 1]:
                    dp[k] = dp[k + 1]
                    ans += dp[k]
                else:
                    dp[k] = 0
                    ans += dp[k]
                    break

        if dp[0] == 0:
            return ans % MOD

    return ans % MOD

