            return "0"
        else:
            key += "0"
            break

    # Try replacing p[i] with 1, and follow the algorithm
    for i in range(len(p)):
        if p[i] == s[-1]:
            break
        if i >= len(p) - k or i < len(p) - 1 or p[i + 1] == s[-1]:
            break
        if p[i] == "1":
            if p[i + 1] == "1":
                break
            elif p[i + 1] == "0":
                new_key = "0" * i + "1" + "0" * (k - 1 - i)
                if new_key + s not in [new_key + key for new_key in [key + "0" if i != len(p) - 1 else key]]:
                    key += "1"
                else:
                    key += "0" * i + "1" + "0" * (k - 1 - i)
