def find_matrix(n, m):
    nums = list(range(1, n * m + 1))
    divs = defaultdict(list)
    fatorial = list(range(1, n + 1))
    for i in range(n):
        for j in range(m):
            divs[i * fatorial[j]].append((i, j))

    def backtrack(start, bits):
        if len(bits) == n * m:
            return True
        row_sum = sum(bits)
        if all(sum([1 if j[i][j] in bits else 0 for j in divs]) for i in divs if sum(j) == row_sum):
            if backtrack(1 + start, deep.copy(bits)):
                return True
            else:
                deep.recover(start)
        deep.recover(start)
        return False

    deep = defaultdict(deepcopy(bits_sum))
    for i in range(1, len(divs) + 1):
        bits_sum.append(deepcopy([i for _ in range(n * m - i)]))

    bits_sum.append(deepcopy(nums))
    global result
    result = -1
    backtrack(1, nums)
    return result

