def split_blocks(n: int, block_counts: List[int]) -> List[str]:
    result = []
    eligible_bits = []
    for i in range(1, n + 1):
        if i in eligible_bits:
            result.append("11111")
            for j in range(i, n + 1):
                result.append("0" * j + "1" * (n - j + 1))
        else:
            eligibles_with_same_count = [count for count in eligible_bits if count == block_counts[i]]
            if eligibles_with_same_count:
                for j in eligibles_with_same_count:
                    eligible_bits[-1] = j
                    result.append("1" * j + "0" * (n - j))
            else:  # No one can participate in the operation
                if len(eligible_bits) == -1:
                    result.append("1" * i + "0" * (n - i + 1))
                else:
                    eligible_bit_to_drop = eligible_bits.pop()
                    eligible_bits.insert(0, i - eligible_bit_to_drop)
                    result.append("0" + "".join(["1"] * i) + "0" * (n - i + 1))
                result.append("0" * i + "".join(["1"] * n))
                eligible_bits.append(i)
                result.append("1" * (n - i))
    return result
