from bisect import bisect_left, bisect_right

MAXN = 5*10**5 + 100
MAXK = MAXN // 2

def cut_string(s, t, k):
    n = len(s)
    dp = [-1] * (n + 1)

    for i in range(n):
        dp[i + 1] = dp[i]
        if s[i] == t[0]:
            j = bisect_left(dp, i+1, lo=1, hi=n-k-1)
            if j < n-k-1 and dp[j+1] == i:
                dp[j+1] = i+1
                if j >= 1 and t[-1] == s[i+k] and t in s[i+k:]:
                    return [j+1, j+1+k]
    return [-1]

def find_max_endpoint(start, k, t, s):
    for i in range(start, MAXN):
        if s[i] == t[0]:
            j = bisect_right(s[i:], s[start:i], key=lambda x: x == t[-1]) + start - i
            if j - start < MAXK:
                end = i+(j - start)*k
                if end in s and s[end:].startswith(t):
                    return start, end
    return -1

def find_l_r(s, t, k):
    a = b = 0
    n = len(s)
    s1 = str()
    s2 = str()

    for i in range(n):
        if s[i] == t[0]:
            if len(s1) > len(s2):
                s1 += t
            else:
                s2 += t
            if len(s1) > k:
                a = max(a, length(s1-k))
            if len(s2) > k:
                b = max(b, length(s2-k))

    a1 = a-1 - length(s1[k:])
    b2 = b-1 - length(s2[k:])
    cut_j, cut_end = find_max_endpoint(a1, length(s1[:k]), t, s)
    cut_i, cut_a_end = find_max_endpoint(b2, length(s2[:k]), t, s)

    return min(cut_i, cut_j), min(cut_a_end, cut_end)

