    result_matrix = [[0] * m for _ in range(n)]

    # Fill the first n/2 rows from left to right
    for i in range(n // 2):
        for j in range(m):
            row_val = max(matrix[i][j], matrix[i + n // 2][j])
            result_matrix[i][j] = row_val

