    for i in range(n // 2, n):
        for j in range(m):
            row_val = max(matrix[i][j], matrix[i - n // 2][j])
            result_matrix[i][j] = row_val

    # Fill the rest of the matrix to satisfy bitonic rows and column conditions
    for i in range(n):
        row = [max(matrix[i][j], result_matrix[i][j + 1]) for j in range(m - 1)]
        value_at_start = 1
        for j in range(m - 2, -1, -1):
            current_val = max(row[j + 1], value_at_start)
            result_matrix[i][j] = current_val
            value_at_start = current_val + 1

