    for i in range(1, len(p)+1):
        for j in range(1, k+1):
            if p[-i] == s[-j]:
                dp[i][j] = 1 + dp[i-1][j-1]
            else:
                dp[i][j] = dp[i-1][j]

    prefix = ""
    for i in range(len(p), 0, -1):
        if dp[i][k] == 1 + dp[i-1][k-1]:
            prefix += "1"
            k -= 1
        else:
            break

    if len(prefix) != k:
        return "0"
    else:
