def number_cubes(n):
    cube = [[0 for _ in range(n)] for _ in range(n)]
    stack = [(0, 0, 0, 1)]
    numbers = [0] * (n ** 3)

    while stack:
        i, j, k, number = stack.pop()

        if numbers[number]:
            return None

        cube[i][j] = number
        numbers[number] = 1

        if k < n - 1:
            stack.append((i + 1, j, k + 1, number + 1))

        if (i + 1) < n:
            stack.append((i + 1, j, 0, number + 1))

        if j < n - 1:
            stack.append((i, j + 1, 0, number + 1))

        if (k + 1) < n:
            stack.append((i, j, k + 1, number + 1))

    return cube

