import bisect

def max_product_query(nums):
    # Helper function to calculate the maximum product of two elements in the sorted segment of nums
    def max_product(start, end, target):
        def search(ar, target):
            return bisect.bisect_left(ar, target)
        if start > end:
            return 0
        idx_end = search(nums[start:end+1], target)
        if idx_end:
            return target-1 if idx_end == start else nums[idx_end]-1
        # In case nums[start:end+1] == [target-1] or [target] in this case, we need to move our boundary
        # This case happens only when the beginning of the ordered segment is shifted
        if idx_end == 0:
            start += 1
        else:
            idx_start = search(nums[start:end+1][::-1], target)
            if idx_start:
                return min(nums[idx_start], target-1) if idx_start == end else nums[idx_start]
            return min(nums[idx_start], target-1) if idx_start else nums[idx_start]

        return -1

    # Calculate the query result using dynamic programming
    dp = [0] * (len(nums) + 1)    
    for i in range(len(nums)):
        dp[i] = max_product_query(dp, dp[i], -nums[i]) if i <= len(nums)-2 else nums[i]
    return max_product_query(dp, dp[::-1], target)

