def is_bitonic(arr):
    return arr[1:] >= arr[:-1] and arr[:-1] >= arr[1:]

def find_bitonic_matrix(n, m):
    # Ensure each number from 1 to n*m appears exactly once in the matrix
    matrix = [[i + (j - 1) * n for j in range(1, m + 1)] for i in range(1, n + 1)]

    # Flip the matrix to transform it into a bitonic matrix
    for i in range(n):
        for j in range(1, m - j):
            matrix[i][j], matrix[i][-j-1] = matrix[i][-j-1], matrix[i][j]

    # Transform the matrix back to the original order
    for i in range(n):
        for j in range(1, m - i):
            matrix[i][j], matrix[i][j*(-i-1)] = matrix[i][j*(-i-1)], matrix[i][j]

    # Verify that each row and column are bitonic
    for i in matrix:
        if not is_bitonic(i):
            return -1
    for j in range(m):
        if not is_bitonic([matrix[i][j] for i in range(n)]):
            return -1

    # Verify that S(A) = S(A')
    X = set(max(row) for row in matrix)
    Y = set(max([matrix[i][j] for i in range(n)]) for j in range(m))

    return "#".join("".join(str(col) for col in row) for row in matrix), X, Y

