def find_lookup_tables(K: int, Q: int) -> str:
    lines = [input().split() for _ in range(Q)]
    intervals = [(int(l), int(r), int(v)) for l, r, v in lines]

    def compute_lookup_tables(K: int, intervals: List[tuple]) -> str:
        Q = len(intervals)
        LSBTable = [0] * 2**K
        MSBTable = [0] * 2**K

        for i in range(K):
            for j in range(1 << i):
                LSBTable[i] <<= 1
            for j in range(1 << (K - i - 1)):
                LSBTable[K - i - 1] |= 1 << j

        for l, r, v in intervals:
            high_bits = (r >> (2 * K - K)) - 1
            low_bits = r - (2**K - 1) - (l - 1)
            for j in range(K):
                high_bits >>= 1
                low_bits <<= 1

            LSBTable[low_bits: low_bits + K] = [v] * K
            MSBTable[high_bits: high_bits + K] = [v] * K

        return "possible\n" + "\n".join(f"{LSBTable[i]:08b}" for i in range(2**K)) + "\n" + "\n".join(f"{MSBTable[i]:08b}" for i in range(2**K))

    return compute_lookup_tables(K, intervals) if any(interval[2] != 0 for interval in intervals) else "impossible\n" + " ".join(["0"] * 16 * 16)

