    # Function to find the first subcube that contains the given three numbers
    def find_first_subcube(x, y, z):
        if (x, y, z) not in number_to_subcube[x]:
            return len(number_to_subcube[x])
        first = number_to_subcube[x][x, y, z]
        for i in range(x + 1, cube_size):
            if i < len(number_to_subcube[i]):
                next_x = number_to_subcube[i][x, y, z]
                sub = min(first, next_x)
                number_to_subcube[x] = number_to_subcube[x][sub] = min(next_x, number_to_subcube[x][sub])
        return first

    # Process the given numbers and update the subcube mappings
    for i, x in enumerate(numbers[1:], start=1):
        for y in numbers[1:]:
            find_first_subcube(i, y, numbers[-1])

    # Unpack the number_to_subcube dictionary into subcubes
    def subcube(x, y, z):
        return [(find_first_subcube(y, find_first_subcube(x, z, y), z), find_first_subcube(x, z, y) + 1)]

    # Convert the subcubes into layers based on 1-indexed positions
    layers = []
    for x in range(cube_size):
        layer = []
        for y in range(cube_size):
            subcube_x = []
            for z in range(cube_size):
                subcube_x.extend(subcube(x, y, z))
            layer.append(subcube_x)
        layers.append(layer)

    return layers

def print_layers(layers):
    for layer in layers:
        for x in layer:
            print(*x)
        print()

