from math import comb

def mod_mult(n, m):
    return (n % m) * (m - 1) % m

def mod_pawi_temp(n, m, steps):
    if steps == 0:
        return n
    if steps % 2 == 0:
        return mod_pawi_temp(mod_pawi_temp(n, m, steps // 2) * mod_pawi_temp(n, m, steps // 2), m, steps // 2) * mod_pawi_temp((1 - n) % m, m, steps // 2)
    return mod_pawi_temp(n, m, steps) * mod_pawi_temp(n, m, steps) * mod_pawi_temp((1 - n) % m, m, steps)

def mod_pawi(n, m, steps):
    if steps <= n:
        return comb(n, steps) % m
    return comb(n, n) % m - mod_pawi(n, m, n - steps) % m if steps > n else 0

def count_possible_queues(n, p, l, r):
    return ((p - ((1 - p) ** r) % p - ((1 - p) ** (r + 1) - (1 - p)) % p) * mod_pawi(n - 1, p, n - 1) % p + (1 - (p - ((1 - p) ** l) % p) - ((1 - p) ** (l + 1) - (1 - p)) % p) * mod_pawi(n - 1, p, n - 1)) % p

