# Recursive function to calculate combinations modulo large numbers
def combination(n, r, memo={}):
    if r in memo:
        return memo[r]
    if r == 0 or 2*r > n:
        return 1
    val = (combination(n-1, r-1, memo) - 2*combination(n-2, r-1, memo)) % mod
    memo[r] = val
    return val

def calculate_choice_combinations(k, n, memo={}):
    ans = 1
    for i in range(n+1):
        ans = (ans * combination(2*k, 2*i, memo) * combination(2*k, 2*n+2-2*i, memo)) % mod
    return ans

