def is_bitonic(arr):
    return arr[:-1] < arr[1:].all() and arr[-1:] > arr[0:-1].all()

def reconstruct(matrix, rows, cols):
    # Sort each row
    sorted_rows = [matrix.flatten()[argsort(matrix.flatten()[i])].reshape(rows, cols) for i in range(rows)]
    # Sort each column
    sorted_cols = [matrix.flatten()[argsort(matrix.flatten()[i], axis=1)].reshape(rows, cols) for i in range(cols)]

    # Reconstruct the matrix using sorted rows and columns
    sorted_matrix = sorted_cols[0].reshape(rows, cols)
    for row in range(rows):
        sorted_matrix = matrix([[sorted_matrix[i] if j != i else sorted_cols[i][i^j] for j in range(cols)] for i in range(cols)])

    return sorted_matrix

