def find_key(p, s, k):
    if len(p) < k:
        return 0

    # Multiply p by the length of s to compare characters
    p = p + "+"*k
    for j in range(k):
        # Initialize the bit corresponding to current position in s
        bit = p[j]
        # Check half of the key bit sequence
        for i in range(j + 1, len(p) // 2, 3):
            if bit == p[i]:
                if s[i - (j - 1)] != '0':
                    return 0
            if bit == p[i + 1]:
                if s[i - (j - 1) + 1] != '0':
                    return 0
            if bit == p[i + 2]:
                if s[i - (j - 1) + 2] != '0':
                    return 0
        bit = p[k - j - 1]
        # Check remaining half of the key bit sequence
        for i in range(k - j + 1, len(p) // 2 + k - j, 3):
            if bit == p[i]:
                if s[i - (j - 1)] != '0':
                    return 0
            if bit == p[i + 1]:
                if s[i - (j - 1) + 1] != '0':
                    return 0
            if bit == p[i + 2]:
                if s[i - (j - 1) + 2] != '0':
                    return 0

    return '1' * k

