            for unmatched in range(k // 3):
                left = (n - 1 - choice) // 2 + 1
                if choice > k % 3 or left > k:
                    break
                else:
                    right = n - position - 1 + (1 if choice % 2 == 0 else (1 if choice // 2 > 2 else (overlap - 2 if choice // 2 > 2 and choice == k else 0))) # 1 if choice % 2 == 0 else 2 if choice == 1 else 3 if choice < 2 else 4
                    result += dp(left, k - choice) * dp(right, k - choice)

        return result % _mod

    return dp(n - 1, k - 1)

def solve():
    n, k = map(int, input().split())
    print(number_of_trees(n, k))

solve()
